-- Stage 3.4.1 - Canonical Subsystem Registry & Capability Contract
-- Target: MariaDB/MySQL. Applies after Stage 3.3.10 / repository migration level 17.
--
-- Architectural boundary:
--   * Adds an APTS-MO01-owned canonical registry of subsystem identities and declared capabilities.
--   * Canonical subsystem identity is independent of runtime host/port/endpoint and component instance.
--   * Capability contracts describe compatibility/authority semantics only; they do NOT select a route.
--   * Stage 3.4.1 does NOT probe subsystem health, bind runtime endpoints, resolve candidates,
--     select a route, delegate work, query Governance, dispatch target actions, or actuate targets.
--   * REGISTRATION != AVAILABILITY; CAPABILITY != PERMISSION; REGISTRY != AUTHORIZATION;
--     ROUTE SELECTION != EXECUTION.
--   * aptsGSS / GOV-PLANE remains the sole Governance/authorization authority.

USE apts_mission_orchestrator;

CREATE TABLE IF NOT EXISTS subsystem_registry_snapshots (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    registry_id VARCHAR(100) NOT NULL,
    registry_version INT UNSIGNED NOT NULL,
    schema_version VARCHAR(100) NOT NULL,
    canonical_sha256 CHAR(64) NOT NULL,
    canonical_json LONGTEXT NOT NULL,
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_subsystem_registry_snapshot (registry_id, registry_version),
    CONSTRAINT chk_subsystem_registry_snapshot_json CHECK (json_valid(canonical_json))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS canonical_subsystems (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    subsystem_id VARCHAR(64) NOT NULL,
    registry_id VARCHAR(100) NOT NULL,
    registry_version INT UNSIGNED NOT NULL,
    schema_version VARCHAR(100) NOT NULL,
    subsystem_type VARCHAR(100) NOT NULL,
    status VARCHAR(40) NOT NULL,
    canonical_sha256 CHAR(64) NOT NULL,
    canonical_json LONGTEXT NOT NULL,
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_canonical_subsystem_id (subsystem_id),
    KEY idx_canonical_subsystem_registry (registry_id, registry_version, subsystem_id),
    CONSTRAINT chk_canonical_subsystem_json CHECK (json_valid(canonical_json))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS subsystem_capability_contracts (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    capability_contract_id VARCHAR(180) NOT NULL,
    capability_id VARCHAR(128) NOT NULL,
    subsystem_id VARCHAR(64) NOT NULL,
    capability_version INT UNSIGNED NOT NULL,
    schema_version VARCHAR(100) NOT NULL,
    status VARCHAR(40) NOT NULL,
    canonical_sha256 CHAR(64) NOT NULL,
    canonical_json LONGTEXT NOT NULL,
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_subsystem_capability_contract_id (capability_contract_id),
    UNIQUE KEY uq_subsystem_capability_id (capability_id),
    UNIQUE KEY uq_subsystem_capability_version (subsystem_id, capability_id, capability_version),
    KEY idx_subsystem_capability_subsystem (subsystem_id, capability_id),
    CONSTRAINT fk_subsystem_capability_subsystem FOREIGN KEY (subsystem_id) REFERENCES canonical_subsystems(subsystem_id),
    CONSTRAINT chk_subsystem_capability_json CHECK (json_valid(canonical_json))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


